import json
with open('/app/resources/treasury_bulletin_1960_10.json', 'r') as f:
    data = json.load(f)

# Print keys at top level
def print_structure(d, indent=0):
    if isinstance(d, dict):
        print(' ' * indent + '{')
        for k, v in d.items():
            print(' ' * (indent+2) + f'\"{k}\": ')
            if isinstance(v, dict):
                print_structure(v, indent+4)
            elif isinstance(v, list):
                print(' ' * (indent+2) + '[')
                if len(v) > 0:
                    print_structure(v[0], indent+4)
                print(' ' * (indent+2) + ']')
            else:
                print(f' {type(v).__name__}')
    elif isinstance(d, list):
        print(' ' * indent + '[')
        if len(d) > 0:
            print_structure(d[0], indent+2)
        print(' ' * indent + ']')

print_structure(data)
