import json
with open('/app/resources/treasury_bulletin_1960_10.json', 'r') as f:
    data = json.load(f)

# Find tables in the data
def find_tables(d):
    tables = []
    if isinstance(d, dict):
        for k, v in d.items():
            if k == 'tables' or 'table' in k.lower():
                tables.append(v)
            else:
                tables.extend(find_tables(v))
    elif isinstance(d, list):
        for item in d:
            tables.extend(find_tables(item))
    return tables

tables = find_tables(data)
print(f'Found {len(tables)} table(s)')
for i, t in enumerate(tables[:5]):
    print(f'\\nTable {i}: {type(t)}')
    if isinstance(t, list) and len(t) > 0:
        print(f'  Rows: {len(t)}')
        if isinstance(t[0], list):
            print(f'  Cols: {len(t[0])}')
            if len(t) > 0:
                print(f'  First row: {t[0][:5]}')
